#!/usr/bin/env bash
set -euo pipefail
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"; source "$SCRIPT_DIR/network_discovery.sh"; REPORT=${1:?Uso: $0 <pasta_do_relatorio>}; IFACE_LAN=$(select_lan_interface); RANGE=$(select_scan_range "$IFACE_LAN" "${SCAN_RANGE:-}"); record_interface_selection "$REPORT" "$IFACE_LAN" "$RANGE"; TARGETS="$REPORT/live_hosts.txt"; [[ -s "$TARGETS" ]] || { fail 'Descoberta sem hosts; scan profundo recusado'; exit 1; }; SCRIPTS=default,safe; [[ ${VULN:-0} == 1 ]] && SCRIPTS=default,vuln; sudo nmap -sS -sV -O --osscan-guess --version-intensity 5 --script "$SCRIPTS" --max-retries 2 --host-timeout 120s -oA "$REPORT/deep" -iL "$TARGETS" | tee "$REPORT/deep.console"; test -s "$REPORT/deep.xml"